/**
 * SAFA — Unified Tactile Controls (Button, IconButton, Tag, Avatar) (Build 02.2)
 * High-craft, velvety cohesion, soft satin active states, dual-theme support.
 * Refactored to standard cva (class-variance-authority) and cn utility architecture.
 */

import React, { ReactNode, ButtonHTMLAttributes } from 'react';
import { cva, type VariantProps } from 'class-variance-authority';
import { X, Loader2 } from 'lucide-react';
import { cn } from '../../lib/utils';

export const buttonVariants = cva(
  'inline-flex items-center justify-center font-medium tracking-tight transition-all duration-150 cursor-pointer disabled:opacity-40 disabled:cursor-not-allowed disabled:active:scale-100 disabled:pointer-events-none select-none active:scale-[0.97] focus-visible:outline-none focus-safa',
  {
    variants: {
      variant: {
        primary:
          'bg-[#111116] text-white hover:bg-[#1E1E24] border border-black/10 shadow-xs dark:bg-[#EBEBEF] dark:text-[#0C0C0E] dark:hover:bg-[#F5F5F8] dark:border-white/10',
        secondary:
          'bg-zinc-100 text-zinc-800 hover:bg-zinc-200 hover:text-black border border-black/[0.05] shadow-xs dark:bg-[#16161B] dark:text-[#D4D4D8] dark:hover:bg-[#1C1C22] dark:hover:text-white dark:border-white/[0.06]',
        'white-pill':
          'bg-[#EBEBEF] text-[#0C0C0E] font-semibold hover:bg-[#F5F5F8] shadow-xs border border-white/20',
        'dark-pill':
          'bg-[#111116] text-[#EDEDEF] hover:bg-[#1C1C22] hover:text-white border border-black/10 dark:border-white/[0.06] shadow-xs',
        ghost:
          'bg-transparent text-zinc-600 hover:bg-black/[0.04] hover:text-zinc-950 dark:text-[#92929B] dark:hover:bg-white/[0.04] dark:hover:text-[#EDEDEF]',
        outline:
          'bg-transparent text-zinc-800 border border-black/[0.1] hover:bg-black/[0.03] dark:text-[#D4D4D8] dark:border-white/[0.08] dark:hover:bg-white/[0.04]',
        rose:
          'bg-rose-50 text-rose-800 hover:bg-rose-100 border border-rose-200/60 dark:bg-[#18181F] dark:text-[#D4C5B9] dark:hover:bg-[#20202A] dark:border-white/[0.07]',
      },
      size: {
        xs: 'text-[11px] px-2.5 py-1 rounded-full gap-1',
        sm: 'text-xs px-3.5 py-1.5 rounded-full gap-1.5',
        md: 'text-sm px-4 sm:px-5 py-2 sm:py-2.5 rounded-full gap-2',
        lg: 'text-base px-6 py-3 rounded-full gap-2.5',
      },
      fullWidth: {
        true: 'w-full',
        false: '',
      },
    },
    defaultVariants: {
      variant: 'primary',
      size: 'md',
      fullWidth: false,
    },
  }
);

// --- Button ---
export interface ButtonProps
  extends ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  children: ReactNode;
  icon?: ReactNode;
  loading?: boolean;
}

export function Button({
  variant = 'primary',
  size = 'md',
  children,
  icon,
  fullWidth = false,
  loading = false,
  className = '',
  disabled,
  ...props
}: ButtonProps) {
  return (
    <button
      className={cn(buttonVariants({ variant, size, fullWidth }), className)}
      disabled={disabled || loading}
      {...props}
    >
      {loading ? (
        <Loader2 className="w-3.5 h-3.5 animate-spin shrink-0" />
      ) : (
        icon && <span className="shrink-0">{icon}</span>
      )}
      <span className="whitespace-nowrap">{children}</span>
    </button>
  );
}

export const iconButtonVariants = cva(
  'rounded-full inline-flex items-center justify-center transition-all duration-150 cursor-pointer select-none active:scale-90 focus-visible:outline-none focus-safa',
  {
    variants: {
      variant: {
        primary:
          'bg-[#111116] text-white hover:bg-[#1E1E24] shadow-xs dark:bg-[#EBEBEF] dark:text-[#0C0C0E] dark:hover:bg-[#F5F5F8]',
        white:
          'bg-white text-zinc-900 hover:bg-zinc-100 shadow-xs border border-black/[0.06] dark:bg-[#EBEBEF] dark:text-[#0C0C0E] dark:hover:bg-[#F5F5F8]',
        secondary:
          'bg-zinc-100 text-zinc-800 hover:bg-zinc-200 border border-black/[0.05] dark:bg-[#16161B] dark:text-[#D4D4D8] dark:hover:bg-[#1E1E26] dark:border-white/[0.06]',
        ghost:
          'bg-transparent text-zinc-600 hover:bg-black/[0.04] hover:text-zinc-950 dark:text-[#92929B] dark:hover:bg-white/[0.04] dark:hover:text-[#EDEDEF]',
        rose:
          'bg-rose-50 text-rose-800 hover:bg-rose-100 border border-rose-200/60 dark:bg-[#18181F] dark:text-[#D4C5B9] dark:hover:bg-[#20202A] dark:border-white/[0.07]',
      },
      size: {
        xs: 'w-7 h-7 text-xs',
        sm: 'w-8 h-8 text-xs',
        md: 'w-9 h-9 sm:w-10 sm:h-10 text-sm',
        lg: 'w-11 h-11 text-base',
      },
    },
    defaultVariants: {
      variant: 'ghost',
      size: 'md',
    },
  }
);

// --- IconButton ---
export interface IconButtonProps
  extends ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof iconButtonVariants> {
  icon: ReactNode;
  label?: string;
  loading?: boolean;
}

export function IconButton({
  icon,
  variant = 'ghost',
  size = 'md',
  label,
  loading = false,
  className = '',
  disabled,
  ...props
}: IconButtonProps) {
  return (
    <button
      type="button"
      className={cn(
        iconButtonVariants({ variant, size }),
        (disabled || loading) && 'opacity-40 cursor-not-allowed',
        className
      )}
      title={label}
      aria-label={label}
      disabled={disabled || loading}
      {...props}
    >
      {loading ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : icon}
    </button>
  );
}

// --- Tag / Badge ---
export interface TagProps {
  children?: ReactNode;
  label?: string;
  variant?: 'neutral' | 'amber' | 'purple' | 'green' | 'red' | 'rose' | 'blue';
  color?: 'neutral' | 'amber' | 'purple' | 'green' | 'red' | 'rose' | 'blue';
  size?: 'sm' | 'md';
  onRemove?: () => void;
  className?: string;
}

export function Tag({
  children,
  label,
  variant,
  color,
  size = 'sm',
  onRemove,
  className = '',
}: TagProps) {
  const effectiveVariant = variant || color || 'neutral';
  const sizeStyle = size === 'sm' ? 'text-[11px] px-2.5 py-0.5' : 'text-xs px-3 py-1';

  const variantStyle = {
    neutral:
      'bg-zinc-100 text-zinc-700 border border-black/[0.06] dark:bg-white/[0.04] dark:text-[#A1A1AA] dark:border-white/[0.06]',
    amber:
      'bg-amber-50 text-amber-800 border border-amber-300/40 font-medium dark:bg-amber-400/[0.08] dark:text-amber-300/90 dark:border-amber-400/20',
    purple:
      'bg-purple-50 text-purple-800 border border-purple-300/40 font-medium dark:bg-purple-400/[0.08] dark:text-purple-300/90 dark:border-purple-400/20',
    green:
      'bg-emerald-50 text-emerald-800 border border-emerald-300/40 font-medium dark:bg-emerald-400/[0.08] dark:text-emerald-300/90 dark:border-emerald-400/20',
    red:
      'bg-rose-50 text-rose-800 border border-rose-300/40 font-medium dark:bg-rose-400/[0.08] dark:text-rose-300/90 dark:border-rose-400/20',
    rose:
      'bg-stone-100 text-stone-800 border border-stone-200 font-medium dark:bg-white/[0.05] dark:text-[#D4C5B9] dark:border-white/[0.07]',
    blue:
      'bg-blue-50 text-blue-800 border border-blue-300/40 font-medium dark:bg-blue-400/[0.08] dark:text-blue-300/90 dark:border-blue-400/20',
  }[effectiveVariant];

  return (
    <span
      className={`inline-flex items-center gap-1 rounded-full tracking-tight whitespace-nowrap ${sizeStyle} ${variantStyle} ${className}`}
    >
      <span>{children || label}</span>
      {onRemove && (
        <button
          type="button"
          aria-label="Remove"
          onClick={(e) => {
            e.stopPropagation();
            onRemove();
          }}
          className="relative hover:opacity-75 transition-opacity p-0.5 cursor-pointer after:absolute after:-inset-2 after:content-['']"
        >
          <X className="w-2.5 h-2.5" />
        </button>
      )}
    </span>
  );
}

// --- Avatar ---
export interface AvatarProps {
  name?: string;
  src?: string;
  size?: 'xs' | 'sm' | 'md' | 'lg';
  status?: 'online' | 'offline';
  className?: string;
}

export function Avatar({
  name = 'Safa',
  src,
  size = 'md',
  status,
  className = '',
}: AvatarProps) {
  const sizeStyle = {
    xs: 'w-6 h-6 text-[10px]',
    sm: 'w-7 h-7 text-xs',
    md: 'w-9 h-9 text-sm',
    lg: 'w-12 h-12 text-base font-semibold',
  }[size];

  const initial = name ? name.charAt(0).toUpperCase() : 'S';

  return (
    <div className="relative inline-block shrink-0">
      {src ? (
        <img
          src={src}
          alt={name}
          className={`rounded-full object-cover ring-1 ring-black/[0.06] dark:ring-white/10 ${sizeStyle} ${className}`}
          referrerPolicy="no-referrer"
        />
      ) : (
        <div
          className={`rounded-full bg-zinc-200 text-zinc-800 dark:bg-[#1A1A20] dark:text-[#D4D4D8] flex items-center justify-center font-medium ring-1 ring-black/[0.06] dark:ring-white/10 ${sizeStyle} ${className}`}
        >
          {initial}
        </div>
      )}
      {status && (
        <span
          className={`absolute bottom-0 right-0 rounded-full ring-2 ring-white dark:ring-[#0B0B0D] ${
            status === 'online' ? 'bg-emerald-400' : 'bg-zinc-400 dark:bg-zinc-500'
          } ${size === 'xs' || size === 'sm' ? 'w-2 h-2' : 'w-2.5 h-2.5'}`}
        />
      )}
    </div>
  );
}

/**
 * SAFA — Obsidian Liquid Glass (SOLG) Reusable Surfaces & Card Primitives (Build 02.2)
 * Authentic layered materials: Canvas -> Surface -> Elevated -> Liquid Glass
 * Dual-theme (Obsidian Dark / Porcelain Light) responsive.
 */

import React, { ReactNode, HTMLAttributes } from 'react';

export type SurfaceVariant =
  | 'surface'            // Primary container surface (#0E0E13 / white)
  | 'surfaceSecondary'   // Secondary container surface (#0B0C11 / #F8F8FA)
  | 'elevated'           // Elevated interactive surface (#131318 / white)
  | 'glass'              // Translucent liquid glass with blur
  | 'compact'            // Ultra-compact quiet list container
  | 'flat'               // Clean minimal container without shadow
  | 'outline';           // Pure hairline container

export interface SurfaceProps extends HTMLAttributes<HTMLDivElement> {
  children: ReactNode;
  variant?: SurfaceVariant;
  rounded?: 'sm' | 'md' | 'lg' | 'xl' | '2xl' | '3xl' | 'full';
  padding?: 'none' | 'xs' | 'sm' | 'md' | 'lg' | 'xl';
  hoverable?: boolean;
  interactive?: boolean;
}

export function Surface({
  children,
  variant = 'surface',
  rounded = '2xl',
  padding = 'md',
  hoverable = false,
  interactive = false,
  className = '',
  ...props
}: SurfaceProps) {
  const roundMap = {
    sm: 'rounded-lg',
    md: 'rounded-xl',
    lg: 'rounded-2xl',
    xl: 'rounded-[22px]',
    '2xl': 'rounded-[26px]',
    '3xl': 'rounded-[32px]',
    full: 'rounded-full',
  }[rounded];

  const padMap = {
    none: 'p-0',
    xs: 'p-2 sm:p-2.5',
    sm: 'p-3 sm:p-3.5',
    md: 'p-4 sm:p-5',
    lg: 'p-5 sm:p-6',
    xl: 'p-6 sm:p-8',
  }[padding];

  const variantMap = {
    surface:
      'bg-white dark:bg-[#0E0E13] border border-black/[0.045] dark:border-white/[0.025] shadow-[0_4px_16px_rgba(0,0,0,0.03)] dark:shadow-[inset_0_1px_0_0_rgba(255,255,255,0.04),0_8px_24px_-4px_rgba(0,0,0,0.5)]',
    surfaceSecondary:
      'bg-[#F8F8FA] dark:bg-[#0B0C11] border border-black/[0.035] dark:border-white/[0.02] shadow-[inset_0_1px_0_0_rgba(255,255,255,0.8)] dark:shadow-[inset_0_1px_0_0_rgba(255,255,255,0.03)]',
    elevated:
      'bg-white dark:bg-[#131318] border border-black/[0.05] dark:border-white/[0.035] shadow-[0_8px_28px_rgba(0,0,0,0.05)] dark:shadow-[inset_0_1px_0_0_rgba(255,255,255,0.06),0_16px_36px_-6px_rgba(0,0,0,0.65)]',
    glass:
      'bg-white/80 dark:bg-[#0E0E13]/55 backdrop-blur-2xl border border-black/[0.04] dark:border-white/[0.03] shadow-[0_8px_24px_rgba(0,0,0,0.04)] dark:shadow-[inset_0_1px_0_0_rgba(255,255,255,0.04),0_18px_40px_-10px_rgba(0,0,0,0.65)]',
    compact:
      'bg-white/90 dark:bg-[#0B0C11] border border-black/[0.03] dark:border-white/[0.02] shadow-xs',
    flat:
      'bg-zinc-100/80 dark:bg-[#0B0C11]/80 border-transparent',
    outline:
      'bg-transparent border border-black/[0.08] dark:border-white/[0.04]',
  }[variant];

  const hoverStyle =
    hoverable || interactive
      ? 'transition-all duration-200 hover:-translate-y-0.5 hover:shadow-md dark:hover:shadow-[0_16px_36px_-6px_rgba(0,0,0,0.7)] cursor-pointer active:scale-[0.99]'
      : '';

  return (
    <div
      className={`relative ${roundMap} ${padMap} ${variantMap} ${hoverStyle} ${className}`}
      {...props}
    >
      {children}
    </div>
  );
}

// Backward-compatible alias
export const Card = Surface;

export function CardHeader({ className = '', ...props }: HTMLAttributes<HTMLDivElement>) {
  return <div className={`flex flex-col space-y-1.5 pb-3 ${className}`} {...props} />;
}

export function CardTitle({ className = '', ...props }: HTMLAttributes<HTMLHeadingElement>) {
  return <h3 className={`text-base font-semibold tracking-tight text-zinc-950 dark:text-white ${className}`} {...props} />;
}

export function CardDescription({ className = '', ...props }: HTMLAttributes<HTMLParagraphElement>) {
  return <p className={`text-xs text-zinc-500 dark:text-zinc-400 ${className}`} {...props} />;
}

export function CardContent({ className = '', ...props }: HTMLAttributes<HTMLDivElement>) {
  return <div className={`py-1.5 ${className}`} {...props} />;
}

export function CardFooter({ className = '', ...props }: HTMLAttributes<HTMLDivElement>) {
  return <div className={`flex items-center pt-3 border-t border-black/[0.04] dark:border-white/[0.03] ${className}`} {...props} />;
}

export function GlassSurface({
  children,
  className = '',
  ...props
}: SurfaceProps) {
  return (
    <Surface variant="glass" rounded="2xl" padding="md" className={className} {...props}>
      {children}
    </Surface>
  );
}

export const GlassCard = GlassSurface;

export function ElevatedSurface({
  children,
  className = '',
  ...props
}: SurfaceProps) {
  return (
    <Surface variant="elevated" rounded="2xl" padding="md" className={className} {...props}>
      {children}
    </Surface>
  );
}

/**
 * SAFA — Unified Velvet Form Inputs (Build 02.2)
 * High-craft tactile inputs, dual-theme support (Obsidian Dark / Matte Light),
 * micro-hairlines, and calm focus rings with cn utility.
 */

import React, { InputHTMLAttributes, TextareaHTMLAttributes, forwardRef, ReactNode } from 'react';
import { Search, X } from 'lucide-react';
import { cn } from '../../lib/utils';

// --- Input ---
export interface InputProps extends InputHTMLAttributes<HTMLInputElement> {
  label?: string;
  error?: string;
  leftIcon?: ReactNode;
  rightIcon?: ReactNode;
}

export const Input = forwardRef<HTMLInputElement, InputProps>(
  ({ label, error, leftIcon, rightIcon, className = '', id, ...props }, ref) => {
    const inputId = id || (label ? `input-${label.replace(/\s+/g, '-').toLowerCase()}` : undefined);
    const helperId = error ? `${inputId}-error` : undefined;
    return (
      <div className="w-full space-y-1.5">
        {label && (
          <label htmlFor={inputId} className="block text-xs font-semibold text-zinc-700 dark:text-[#92929B] tracking-tight">
            {label}
          </label>
        )}
        <div className="relative flex items-center">
          {leftIcon && (
            <div className="absolute left-3.5 text-zinc-400 dark:text-[#71717A] pointer-events-none flex items-center">
              {leftIcon}
            </div>
          )}
          <input
            ref={ref}
            id={inputId}
            aria-invalid={error ? true : undefined}
            aria-describedby={helperId}
            className={cn(
              'w-full bg-white dark:bg-[#131317] border border-black/[0.08] dark:border-white/[0.06] rounded-xl px-3.5 py-2.5 text-sm text-zinc-900 dark:text-[#EDEDEF] placeholder-zinc-400 dark:placeholder-[#5C5C66] transition-all duration-150 focus:outline-none focus:border-black/30 dark:focus:border-white/[0.16] shadow-xs focus-safa',
              leftIcon && 'pl-10',
              rightIcon && 'pr-10',
              error && 'border-rose-500/60 focus:border-rose-500',
              className
            )}
            {...props}
          />
          {rightIcon && (
            <div className="absolute right-3.5 text-zinc-400 dark:text-[#71717A] flex items-center">
              {rightIcon}
            </div>
          )}
        </div>
        {error && <p id={helperId} className="text-xs text-rose-500 mt-1">{error}</p>}
      </div>
    );
  }
);
Input.displayName = 'Input';

// --- Textarea ---
export interface TextareaProps extends TextareaHTMLAttributes<HTMLTextAreaElement> {
  label?: string;
  error?: string;
}

export const Textarea = forwardRef<HTMLTextAreaElement, TextareaProps>(
  ({ label, error, className = '', rows = 3, id, ...props }, ref) => {
    const textareaId = id || (label ? `textarea-${label.replace(/\s+/g, '-').toLowerCase()}` : undefined);
    const helperId = error ? `${textareaId}-error` : undefined;
    return (
      <div className="w-full space-y-1.5">
        {label && (
          <label htmlFor={textareaId} className="block text-xs font-semibold text-zinc-700 dark:text-[#92929B] tracking-tight">
            {label}
          </label>
        )}
        <textarea
          ref={ref}
          id={textareaId}
          rows={rows}
          aria-invalid={error ? true : undefined}
          aria-describedby={helperId}
          className={cn(
            'w-full bg-white dark:bg-[#131317] border border-black/[0.08] dark:border-white/[0.06] rounded-xl p-3.5 text-sm text-zinc-900 dark:text-[#EDEDEF] placeholder-zinc-400 dark:placeholder-[#5C5C66] transition-all duration-150 focus:outline-none focus:border-black/30 dark:focus:border-white/[0.16] resize-y shadow-xs focus-safa',
            error && 'border-rose-500/60 focus:border-rose-500',
            className
          )}
          {...props}
        />
        {error && <p id={helperId} className="text-xs text-rose-500 mt-1">{error}</p>}
      </div>
    );
  }
);
Textarea.displayName = 'Textarea';

// --- SearchBar ---
export interface SearchBarProps {
  value: string;
  onChange: (val: string) => void;
  placeholder?: string;
  onClear?: () => void;
  autoFocus?: boolean;
  className?: string;
}

export function SearchBar({
  value,
  onChange,
  placeholder = 'Search everything in SAFA...',
  onClear,
  autoFocus,
  className = '',
}: SearchBarProps) {
  return (
    <div className={cn('relative w-full flex items-center', className)}>
      <Search className="absolute left-3.5 w-4 h-4 text-zinc-400 dark:text-[#71717A] pointer-events-none" />
      <input
        type="text"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        autoFocus={autoFocus}
        className="w-full bg-white dark:bg-[#131317] border border-black/[0.08] dark:border-white/[0.06] rounded-full pl-10 pr-10 py-2.5 text-sm text-zinc-900 dark:text-[#EDEDEF] placeholder-zinc-400 dark:placeholder-[#5C5C66] focus:outline-none focus:border-black/30 dark:focus:border-white/[0.16] transition-all shadow-xs tracking-tight"
      />
      {value && onClear && (
        <button
          type="button"
          onClick={onClear}
          className="absolute right-3.5 p-1 rounded-full text-zinc-400 hover:text-zinc-900 dark:text-[#71717A] dark:hover:text-[#EDEDEF] transition-colors cursor-pointer"
        >
          <X className="w-3.5 h-3.5" />
        </button>
      )}
    </div>
  );
}

/**
 * SAFA — Tactile Switch / Toggle Component (Build 02.2)
 * Dual-theme (Obsidian / Matte Porcelain) with Radix UI headless accessibility and tactile spring.
 */

import React from 'react';
import * as SwitchPrimitive from '@radix-ui/react-switch';
import { cn } from '../../lib/utils';
import { useIsDark } from './theme';

export interface SwitchProps {
  checked: boolean;
  onChange?: (checked: boolean) => void;
  onCheckedChange?: (checked: boolean) => void;
  label?: string;
  description?: string;
  disabled?: boolean;
  size?: 'sm' | 'md' | 'lg';
  className?: string;
}

export function Switch({
  checked,
  onChange,
  onCheckedChange,
  label,
  description,
  disabled = false,
  size = 'md',
  className = '',
}: SwitchProps) {
  const isDark = useIsDark();

  const handleChange = (val: boolean) => {
    onChange?.(val);
    onCheckedChange?.(val);
  };

  const rootSizes = {
    sm: 'h-5 w-9',
    md: 'h-6 w-11',
    lg: 'h-7 w-12',
  }[size];

  const thumbSizes = {
    sm: 'h-4 w-4 data-[state=checked]:translate-x-4 data-[state=unchecked]:translate-x-0.5 rtl:data-[state=checked]:-translate-x-4 rtl:data-[state=unchecked]:-translate-x-0.5',
    md: 'h-5 w-5 data-[state=checked]:translate-x-5 data-[state=unchecked]:translate-x-0.5 rtl:data-[state=checked]:-translate-x-5 rtl:data-[state=unchecked]:-translate-x-0.5',
    lg: 'h-5 w-5 data-[state=checked]:translate-x-6 data-[state=unchecked]:translate-x-1 rtl:data-[state=checked]:-translate-x-6 rtl:data-[state=unchecked]:-translate-x-1',
  }[size];

  return (
    <label
      className={cn(
        'inline-flex items-center gap-3 cursor-pointer select-none',
        disabled && 'opacity-40 cursor-not-allowed pointer-events-none',
        className
      )}
    >
      <SwitchPrimitive.Root
        checked={checked}
        onCheckedChange={handleChange}
        disabled={disabled}
        className={cn(
          'peer inline-flex shrink-0 cursor-pointer items-center rounded-full border-2 border-transparent transition-colors focus-visible:outline-none focus-safa disabled:cursor-not-allowed',
          rootSizes,
          checked
            ? 'bg-emerald-500 shadow-[0_0_12px_rgba(16,185,129,0.35)]'
            : isDark
            ? 'bg-[#181820] border-white/[0.08]'
            : 'bg-zinc-200 border-black/[0.06]'
        )}
      >
        <SwitchPrimitive.Thumb
          className={cn(
            'pointer-events-none block rounded-full bg-white shadow-md ring-0 transition-transform duration-200 ease-in-out',
            thumbSizes
          )}
        />
      </SwitchPrimitive.Root>

      {(label || description) && (
        <div className="flex flex-col text-left rtl:text-right">
          {label && (
            <span
              className={cn(
                'text-xs font-semibold tracking-tight',
                isDark ? 'text-[#EDEDEF]' : 'text-zinc-900'
              )}
            >
              {label}
            </span>
          )}
          {description && (
            <span
              className={cn(
                'text-[11px] leading-tight',
                isDark ? 'text-[#8E8E98]' : 'text-zinc-500'
              )}
            >
              {description}
            </span>
          )}
        </div>
      )}
    </label>
  );
}

