/**
 * SAFA — Unified Velvet Dropdown / Select Component (Build 02.3)
 * Full WAI-ARIA listbox pattern: aria-haspopup="listbox", aria-activedescendant,
 * Arrow/Home/End/Type-ahead keyboard navigation, Escape dismissal with focus return,
 * focus trap while open, RTL-aware text alignment.
 * Dual-theme (Obsidian / Matte Porcelain) with tactile spring animations.
 */

import React, { useState, useRef, useEffect, ReactNode } from 'react';
import { motion, AnimatePresence } from 'motion/react';
import { ChevronDown, Check } from 'lucide-react';
import { useIsDark } from './theme';

export interface DropdownOption<T extends string = string> {
  value: T;
  label: string;
  icon?: ReactNode;
  description?: string;
  badge?: string;
}

export interface DropdownProps<T extends string = string> {
  options: DropdownOption<T>[];
  value: T;
  onChange: (value: T) => void;
  label?: string;
  placeholder?: string;
  className?: string;
  size?: 'sm' | 'md';
}

export function Dropdown<T extends string = string>({
  options,
  value,
  onChange,
  label,
  placeholder = 'Select an option',
  className = '',
  size = 'md',
}: DropdownProps<T>) {
  const isDark = useIsDark();
  const [isOpen, setIsOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);
  const containerRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const typeAheadRef = useRef<{ chars: string; ts: number }>({ chars: '', ts: 0 });

  const selectedOption = options.find((o) => o.value === value);

  // Close on outside click
  useEffect(() => {
    function handleClickOutside(e: MouseEvent) {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setIsOpen(false);
      }
    }
    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [isOpen]);

  // Open → land focus/active on selected option; Close → restore focus to trigger
  useEffect(() => {
    if (isOpen) {
      const idx = options.findIndex((o) => o.value === value);
      setActiveIndex(idx >= 0 ? idx : 0);
    } else {
      triggerRef.current?.focus({ preventScroll: true });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen]);

  const commit = (index: number) => {
    const opt = options[index];
    if (!opt) return;
    onChange(opt.value);
    setIsOpen(false);
  };

  const handleTriggerKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp' || e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      if (!isOpen) {
        setIsOpen(true);
        return;
      }
      if (e.key === 'ArrowDown') {
        setActiveIndex((i) => Math.min(options.length - 1, i + 1));
      } else if (e.key === 'ArrowUp') {
        setActiveIndex((i) => Math.max(0, i - 1));
      } else {
        commit(activeIndex);
      }
      return;
    }
    if (e.key === 'Escape') {
      if (isOpen) {
        e.preventDefault();
        setIsOpen(false);
      }
      return;
    }
    if (isOpen) typeAhead(e);
  };

  const typeAhead = (e: React.KeyboardEvent) => {
    if (!/^[a-zA-Z0-9\u0600-\u06FF]$/.test(e.key)) return;
    const now = Date.now();
    const chars = now - typeAheadRef.current.ts > 500 ? e.key : typeAheadRef.current.chars + e.key;
    typeAheadRef.current = { chars, ts: now };
    const needle = chars.toLowerCase();
    const idx = options.findIndex((o) => o.label.toLowerCase().startsWith(needle));
    if (idx >= 0) setActiveIndex(idx);
  };

  const sizeClass = size === 'sm' ? 'px-3 py-1.5 text-xs' : 'px-3.5 py-2 text-sm';
  const listId = `dropdown-list-${label || 'default'}`.replace(/\s+/g, '-').toLowerCase();

  return (
    <div className={`relative w-full ${className}`} ref={containerRef}>
      {label && (
        <span
          id={`${listId}-label`}
          className={`block text-xs font-semibold mb-1.5 ${
            isDark ? 'text-[#92929B]' : 'text-zinc-700'
          }`}
        >
          {label}
        </span>
      )}

      <button
        ref={triggerRef}
        type="button"
        onClick={() => setIsOpen(!isOpen)}
        onKeyDown={handleTriggerKeyDown}
        className={`w-full flex items-center justify-between rounded-xl font-medium transition-all duration-150 cursor-pointer select-none focus-safa ${sizeClass} ${
          isDark
            ? 'bg-[#131317] text-[#EDEDEF] border border-white/[0.06] hover:border-white/[0.14] shadow-xs'
            : 'bg-white text-zinc-900 border border-black/[0.08] hover:border-black/[0.18] shadow-xs'
        }`}
        aria-expanded={isOpen}
        aria-haspopup="listbox"
        aria-labelledby={label ? `${listId}-label` : undefined}
        aria-activedescendant={isOpen && activeIndex >= 0 ? `${listId}-opt-${activeIndex}` : undefined}
      >
        <span className="flex items-center gap-2 truncate">
          {selectedOption?.icon && <span className="shrink-0">{selectedOption.icon}</span>}
          <span className="truncate">{selectedOption ? selectedOption.label : placeholder}</span>
        </span>
        <ChevronDown
          className={`w-4 h-4 shrink-0 transition-transform duration-200 ${
            isOpen ? 'rotate-180' : ''
          } ${isDark ? 'text-zinc-400' : 'text-zinc-500'}`}
        />
      </button>

      <AnimatePresence>
        {isOpen && (
          <motion.ul
            id={listId}
            role="listbox"
            aria-labelledby={label ? `${listId}-label` : undefined}
            initial={{ opacity: 0, y: -4, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -4, scale: 0.98 }}
            transition={{ duration: 0.14 }}
            className={`absolute left-0 right-0 mt-1.5 p-1 rounded-2xl z-50 backdrop-blur-2xl shadow-xl overflow-hidden ${
              isDark
                ? 'bg-[#0E0E14]/95 border border-white/[0.07] shadow-[0_20px_40px_rgba(0,0,0,0.8)]'
                : 'bg-white/95 border border-black/[0.06] shadow-[0_16px_36px_rgba(0,0,0,0.08)]'
            }`}
          >
            <div className="max-h-60 overflow-y-auto no-scrollbar space-y-0.5">
              {options.map((option, index) => {
                const isSelected = option.value === value;
                const isActive = index === activeIndex;
                return (
                  <li
                    key={option.value}
                    id={`${listId}-opt-${index}`}
                    role="option"
                    aria-selected={isSelected}
                    onClick={() => commit(index)}
                    onMouseEnter={() => setActiveIndex(index)}
                    className={`w-full flex items-center justify-between px-3 py-2 rounded-xl text-xs sm:text-sm font-medium cursor-pointer text-left rtl:text-right focus-safa-inset ${
                      isActive
                        ? isDark
                          ? 'bg-white/[0.08] text-white'
                          : 'bg-black/[0.05] text-zinc-950'
                        : isDark
                        ? 'text-zinc-300'
                        : 'text-zinc-700'
                    } ${isSelected ? 'font-semibold' : ''}`}
                  >
                    <div className="flex items-center gap-2 truncate pointer-events-none">
                      {option.icon && <span className="shrink-0">{option.icon}</span>}
                      <div className="truncate">
                        <div>{option.label}</div>
                        {option.description && (
                          <div
                            className={`text-[10px] ${
                              isDark ? 'text-zinc-500' : 'text-zinc-400'
                            }`}
                          >
                            {option.description}
                          </div>
                        )}
                      </div>
                    </div>
                    {isSelected && (
                      <Check className="w-3.5 h-3.5 text-emerald-500 shrink-0 ml-2 pointer-events-none" />
                    )}
                  </li>
                );
              })}
            </div>
          </motion.ul>
        )}
      </AnimatePresence>
    </div>
  );
}

/**
 * SAFA — Tactile Range Slider Component (Build 02.3)
 * Dual-theme (Obsidian Dark / Porcelain Light), smooth spring thumb, value readout.
 * RTL-aware: track fills and thumb position mirror under [dir="rtl"].
 * The native <input type="range"> is the accessibility root (keyboard + AT),
 * with aria-valuetext exposing the unit.
 */

import React from 'react';
import { useIsDark } from './theme';

export interface SliderProps {
  value: number;
  onChange: (value: number) => void;
  min?: number;
  max?: number;
  step?: number;
  label?: string;
  unit?: string;
  disabled?: boolean;
  className?: string;
}

export function Slider({
  value,
  onChange,
  min = 0,
  max = 100,
  step = 1,
  label,
  unit = '%',
  disabled = false,
  className = '',
}: SliderProps) {
  const isDark = useIsDark();

  const percentage = Math.min(100, Math.max(0, ((value - min) / (max - min)) * 100));

  return (
    <div
      className={`w-full space-y-2 select-none ${disabled ? 'opacity-40 pointer-events-none' : ''} ${className}`}
    >
      {(label || unit) && (
        <div className="flex items-center justify-between text-xs">
          {label && (
            <span className={`font-semibold tracking-tight ${isDark ? 'text-[#EDEDEF]' : 'text-zinc-800'}`}>
              {label}
            </span>
          )}
          <span className="font-mono text-zinc-500 text-[11px]">
            {value}
            {unit}
          </span>
        </div>
      )}

      {/* RTL mirroring: container is dir-neutral; [dir=rtl] fills from the right */}
      <div className="relative flex items-center h-5 slider-safa" dir="ltr">
        {/* Track background */}
        <div
          className={`w-full h-1.5 rounded-full overflow-hidden ${
            isDark ? 'bg-white/[0.08]' : 'bg-black/[0.08]'
          }`}
        >
          {/* Active filled track */}
          <div
            className="h-full bg-emerald-500 rounded-full transition-all duration-75 shadow-[0_0_8px_rgba(16,185,129,0.35)] slider-fill"
            style={{ width: `${percentage}%` }}
          />
        </div>

        {/* Real hidden range input overlaid for native accessibility & keyboard support */}
        <input
          type="range"
          aria-label={label}
          aria-valuetext={`${value}${unit}`}
          min={min}
          max={max}
          step={step}
          value={value}
          disabled={disabled}
          onChange={(e) => onChange(Number(e.target.value))}
          className="absolute inset-0 w-full h-full opacity-0 cursor-pointer focus-visible:ring-2 focus-visible:ring-emerald-500/55 rounded-full"
        />

        {/* Visual tactile thumb */}
        <div
          className={`absolute pointer-events-none w-4 h-4 rounded-full -translate-x-1/2 shadow-md transition-transform duration-75 slider-thumb ${
            isDark
              ? 'bg-white border-2 border-[#131318] shadow-[0_2px_8px_rgba(0,0,0,0.5)]'
              : 'bg-white border-2 border-emerald-500 shadow-[0_2px_8px_rgba(0,0,0,0.15)]'
          }`}
          style={{ left: `${percentage}%`, ['--thumb-pos' as string]: `${100 - percentage}%` }}
        />
      </div>
    </div>
  );
}

/**
 * SAFA — Unified Velvet Segmented Control (Build 02.3)
 * Seamless dark container matching #111114 with satin pill transitions.
 * Authentic Apple / Linear tactile active cushion for light and dark modes.
 * WAI-ARIA radiogroup pattern: roving tabindex, Arrow/Home/End navigation,
 * Space/Enter selection, RTL-aware arrow mapping (WCAG-compliant keyboard UX).
 */

import React, { useRef } from 'react';
import { motion } from 'motion/react';
import { useIsDark } from './theme';

export interface SegmentOption<T extends string = string> {
  value: T;
  label: string;
  icon?: React.ReactNode;
  badge?: number | string;
}

export interface SegmentedControlProps<T extends string = string> {
  options: SegmentOption<T>[];
  value: T;
  onChange: (val: T) => void;
  label?: string;
  size?: 'sm' | 'md';
  fullWidth?: boolean;
  className?: string;
}

export function SegmentedControl<T extends string = string>({
  options,
  value,
  onChange,
  label,
  size = 'md',
  fullWidth = true,
  className = '',
}: SegmentedControlProps<T>) {
  const isDark = useIsDark();
  const groupRef = useRef<HTMLDivElement>(null);
  const padMap = size === 'sm' ? 'p-1' : 'p-1.5';
  const itemPad = size === 'sm' ? 'px-3 py-1.5 text-xs' : 'px-4 py-2 text-xs sm:text-sm';

  const isRTL =
    typeof document !== 'undefined' &&
    (document.documentElement.getAttribute('dir') === 'rtl' ||
      document.documentElement.dir === 'rtl');

  const selectAt = (index: number) => {
    if (index < 0 || index >= options.length) return;
    onChange(options[index].value);
    // Move focus to the newly selected tab-stop button (roving tabindex)
    const buttons = groupRef.current?.querySelectorAll<HTMLButtonElement>('[role="radio"]');
    buttons?.[index]?.focus();
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    const currentIndex = options.findIndex((o) => o.value === value);
    let next: number | null = null;

    switch (e.key) {
      case 'ArrowDown':
        next = currentIndex + 1;
        break;
      case 'ArrowRight':
        // In RTL, ArrowRight moves to the previous (visually-left) segment
        next = isRTL ? currentIndex - 1 : currentIndex + 1;
        break;
      case 'ArrowLeft':
        next = isRTL ? currentIndex + 1 : currentIndex - 1;
        break;
      case 'ArrowUp':
        next = currentIndex - 1;
        break;
      case 'Home':
        next = 0;
        break;
      case 'End':
        next = options.length - 1;
        break;
      case ' ':
      case 'Enter':
        e.preventDefault();
        return;
      default:
        return;
    }

    e.preventDefault();
    if (next !== null) selectAt(next);
  };

  return (
    <div
      ref={groupRef}
      role="radiogroup"
      aria-label={label}
      onKeyDown={handleKeyDown}
      className={`${
        fullWidth ? 'w-full flex' : 'inline-flex'
      } items-center rounded-full transition-all overflow-x-auto no-scrollbar ${
        isDark
          ? 'bg-[#0E0E14] shadow-[inset_0_1px_0_0_rgba(255,255,255,0.045),0_8px_20px_rgba(0,0,0,0.45)] border border-white/[0.025]'
          : 'bg-zinc-100/90 shadow-[inset_0_1px_1px_0_rgba(0,0,0,0.04)] border border-black/[0.04]'
      } ${padMap} ${className}`}
    >
      <div className={`flex items-center gap-1 ${fullWidth ? 'w-full' : ''}`}>
        {options.map((opt) => {
          const isSelected = opt.value === value;
          const selectedIndex = options.findIndex((o) => o.value === value);
          const isFocusTarget = isSelected || (selectedIndex === -1 && opt === options[0]);
          return (
            <button
              key={opt.value}
              type="button"
              role="radio"
              aria-checked={isSelected}
              tabIndex={isFocusTarget ? 0 : -1}
              onClick={() => onChange(opt.value)}
              className={`relative ${itemPad} rounded-full font-medium transition-all duration-200 flex items-center justify-center gap-1.5 cursor-pointer select-none whitespace-nowrap focus-safa-inset ${
                fullWidth ? 'flex-1' : ''
              } ${
                isSelected
                  ? isDark
                    ? 'text-black font-semibold'
                    : 'text-zinc-950 font-semibold'
                  : isDark
                  ? 'text-[#8E8E98] hover:text-white hover:bg-white/[0.03]'
                  : 'text-zinc-600 hover:text-zinc-950 hover:bg-black/[0.03]'
              }`}
            >
              {isSelected && (
                <motion.div
                  layoutId={`segmented-pill-${options.map((o) => o.value).join('-')}`}
                  className={`absolute inset-0 rounded-full ${
                    isDark
                      ? 'bg-white shadow-[0_2px_10px_rgba(255,255,255,0.15),0_2px_6px_rgba(0,0,0,0.4)]'
                      : 'bg-white shadow-[0_1px_3px_rgba(0,0,0,0.08),0_4px_12px_rgba(0,0,0,0.04)] border border-black/[0.04]'
                  }`}
                  transition={{ type: 'spring', stiffness: 500, damping: 38 }}
                />
              )}
              <span className="relative z-10 flex items-center justify-center gap-1.5">
                {opt.icon && <span className="shrink-0">{opt.icon}</span>}
                <span className="tracking-tight">{opt.label}</span>
                {opt.badge !== undefined && (
                  <span
                    className={`px-1.5 py-0.2 text-[10px] rounded-full font-semibold ${
                      isSelected
                        ? isDark
                          ? 'bg-black text-white'
                          : 'bg-zinc-100 text-zinc-900 border border-black/[0.06]'
                        : isDark
                        ? 'bg-white/[0.08] text-[#92929B]'
                        : 'bg-black/[0.06] text-zinc-600'
                    }`}
                  >
                    {opt.badge}
                  </span>
                )}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

/**
 * SAFA — Breadcrumb Navigation Component (Build 02.2)
 * Dual-theme (Obsidian Dark / Porcelain Light).
 */

import React from 'react';
import { ChevronRight, Home } from 'lucide-react';
import { useIsDark } from './theme';

export interface BreadcrumbItem {
  label: string;
  href?: string;
  icon?: React.ReactNode;
  onClick?: () => void;
  active?: boolean;
}

export interface BreadcrumbProps {
  items: BreadcrumbItem[];
  className?: string;
}

export function Breadcrumb({ items, className = '' }: BreadcrumbProps) {
  const isDark = useIsDark();

  return (
    <nav aria-label="Breadcrumb" className={`flex items-center space-x-1.5 text-xs font-medium ${className}`}>
      {items.map((item, index) => {
        const isLast = index === items.length - 1;
        return (
          <div key={index} className="flex items-center space-x-1.5">
            {index > 0 && (
              <ChevronRight className="w-3.5 h-3.5 text-zinc-400 shrink-0 rtl:rotate-180" />
            )}
            {item.onClick || item.href ? (
              <button
                type="button"
                onClick={item.onClick}
                className={`flex items-center gap-1.5 px-1.5 py-0.5 rounded-md transition-colors cursor-pointer ${
                  isLast || item.active
                    ? isDark
                      ? 'text-[#EDEDEF] font-semibold'
                      : 'text-zinc-950 font-semibold'
                    : isDark
                    ? 'text-[#8E8E98] hover:text-white'
                    : 'text-zinc-500 hover:text-black'
                }`}
              >
                {item.icon}
                <span>{item.label}</span>
              </button>
            ) : (
              <span
                className={`flex items-center gap-1.5 px-1.5 py-0.5 ${
                  isLast || item.active
                    ? isDark
                      ? 'text-[#EDEDEF] font-semibold'
                      : 'text-zinc-950 font-semibold'
                    : isDark
                    ? 'text-[#8E8E98]'
                    : 'text-zinc-500'
                }`}
              >
                {item.icon}
                <span>{item.label}</span>
              </span>
            )}
          </div>
        );
      })}
    </nav>
  );
}

